import { _decorator, Component, Node, math, UITransform, Label, HorizontalTextAlignment } from 'cc';
import { Eventer } from '../../../../scripts/framework/Eventer';
import { ScreenType } from '../../../../scripts/framework/ui/UIView';
import { Global } from '../../../../scripts/main/Global';
import { GameEventType } from '../../../gamesCommon/script/GameEventType';
import { RollBottom } from './RollBottom';
const { ccclass, property } = _decorator;

/**
 * 通用底板横竖屏设置组件
 */
@ccclass('RollSceen')
export class RollSceen extends Component {

    @property(Node)
    private menuNode: Node;
    @property(Node)
    private netstatNode: Node;
    @property(Node)
    private tips0: Node;
    @property(Node)
    private tips1: Node;
    @property(Node)
    private tips2: Node;
    @property(Node)
    private activityNode: Node;
    @property(RollBottom)
    private bottom: RollBottom;
    @property(Node)
    private scoreNode: Node;
    @property(Node)
    private winNumNode: Node;
    @property(Node)
    private betNode: Node;
    @property(Node)
    private autoBtnNode: Node;
    @property(Node)
    private startBtnNode: Node;

    private readonly _menuP0: math.Vec3 = new math.Vec3(560, 10, 0);
    private readonly _netstatP0: math.Vec3 = new math.Vec3(555, 332, 0);
    private readonly _tips0P0: math.Vec3 = new math.Vec3(-204, -233, 0);
    private readonly _tips1P0: math.Vec3 = new math.Vec3(194, -232, 0);
    private readonly _tips2P0: math.Vec3 = new math.Vec3(5, -249, 0);
    private readonly _activityP0: math.Vec3 = new math.Vec3(-576, 0, 0);
    private readonly _bottomP0: math.Vec3 = new math.Vec3(0, -310, 0);
    private readonly _scoreNodeP0: math.Vec3 = new math.Vec3(-635, 0, 0);
    private readonly _winNumNodeP0: math.Vec3 = new math.Vec3(0, 0, 0);
    private readonly _betNodeP0: math.Vec3 = new math.Vec3(239, 2, 0);
    private readonly _autoBtnNodeP0: math.Vec3 = new math.Vec3(407, 4, 0);
    private readonly _startBtnNodeP0: math.Vec3 = new math.Vec3(550, 12, 0);

    private readonly _menuP1: math.Vec3 = new math.Vec3(288, 135, 0);
    private readonly _netstatP1: math.Vec3 = new math.Vec3(280, 580, 0);
    private readonly _tips0P1: math.Vec3 = new math.Vec3(-348, -440, 0);
    private readonly _tips1P1: math.Vec3 = new math.Vec3(343, -510, 0);
    private readonly _tips2P1: math.Vec3 = new math.Vec3(32, -520, 0);
    private readonly _activityP1: math.Vec3 = new math.Vec3(-296, 0, 0);
    // private readonly _activityP1: math.Vec3 = new math.Vec3(-296,200, 0);
    private readonly _bottomP1: math.Vec3 = new math.Vec3(-250, -591, 0);
    private readonly _scoreNodeP1: math.Vec3 = new math.Vec3(-112, 95, 0);
    private readonly _winNumNodeP1: math.Vec3 = new math.Vec3(0, 0, 0);
    private readonly _betNodeP1: math.Vec3 = new math.Vec3(228, 2, 0);
    private readonly _autoBtnNodeP1: math.Vec3 = new math.Vec3(388, 4, 0);
    private readonly _startBtnNodeP1: math.Vec3 = new math.Vec3(525, 12, 0);


    start() {
        this.addListener();
    }

    public onDestroy() {
        this.removeListener();
    }
    // update(deltaTime: number) {
    // }

    private onScreenSwitch(): void {
        if (Global.gameScreenType == ScreenType.Landscape) {
            this.node.angle = 0;
            this.landscape();
        }
        else {
            this.node.angle = 90;
            this.portrait();
        }
    }

    /**
     * 横屏
     */
    private landscape() {
        this.menuNode.setPosition(this._menuP0);
        this.netstatNode.setPosition(this._netstatP0);

        this.bottom.node.setPosition(this._bottomP0);
        this.scoreNode.setPosition(this._scoreNodeP0);
        this.winNumNode.setPosition(this._winNumNodeP0);
        this.betNode.setPosition(this._betNodeP0);
        this.autoBtnNode.setPosition(this._autoBtnNodeP0);
        this.startBtnNode.setPosition(this._startBtnNodeP0);

        this.tips0.getComponent(UITransform).anchorX = 1;
        this.tips0.getComponent(Label).horizontalAlign = HorizontalTextAlignment.RIGHT;
        this.tips0.setPosition(this._tips0P0);

        this.tips1.getComponent(UITransform).anchorX = 0;
        this.tips1.getComponent(Label).horizontalAlign = HorizontalTextAlignment.LEFT;
        this.tips1.setPosition(this._tips1P0);

        this.tips2.setPosition(this._tips2P0);

        this.activityNode.setPosition(this._activityP0);
        // this.activityNode.getComponent(Layout).type=Layout.Type.VERTICAL;
        // this.activityNode.getComponent(Layout).resizeMode=Layout.ResizeMode.CONTAINER;
    }

    /**
     * 竖屏
     */
    private portrait() {
        this.menuNode.setPosition(this._menuP1);
        this.netstatNode.setPosition(this._netstatP1);

        this.bottom.node.setPosition(this._bottomP1);
        this.scoreNode.setPosition(this._scoreNodeP1);
        this.winNumNode.setPosition(this._winNumNodeP1);
        this.betNode.setPosition(this._betNodeP1);
        this.autoBtnNode.setPosition(this._autoBtnNodeP1);
        this.startBtnNode.setPosition(this._startBtnNodeP1);

        this.tips0.getComponent(UITransform).anchorX = 0;
        this.tips0.getComponent(Label).horizontalAlign = HorizontalTextAlignment.LEFT;
        this.tips0.setPosition(this._tips0P1);

        this.tips1.getComponent(UITransform).anchorX = 1;
        this.tips1.getComponent(Label).horizontalAlign = HorizontalTextAlignment.RIGHT;
        this.tips1.setPosition(this._tips1P1);

        this.tips2.setPosition(this._tips2P1);

        this.activityNode.setPosition(this._activityP1);
        // this.activityNode.getComponent(Layout).type=Layout.Type.VERTICAL;
        // this.activityNode.getComponent(Layout).resizeMode=Layout.ResizeMode.CONTAINER;

    }

    private addListener(): void {
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    private removeListener(): void {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }
}

