import { _decorator, Component, Node, math, UITransform, Label, HorizontalTextAlignment, Vec3, SpriteFrame, Sprite } from 'cc';
import { Eventer } from '../../../../../scripts/framework/Eventer';
import { GameEventType } from '../../../../gamesCommon/script/GameEventType';
import { Global } from '../../../../../scripts/main/Global';
import { ScreenType } from '../../../../../scripts/framework/ui/UIView';
;
const { ccclass, property } = _decorator;

/**
 * sprite横竖屏设置组件
 */
@ccclass('SpriteScreenSwitch')
export class SpriteScreenSwitch extends Component {

    @property(SpriteFrame)
    private horSpr: SpriteFrame;
    @property(SpriteFrame)
    private verSpr: SpriteFrame;



    start() {
        this.addListener();
        this.onScreenSwitch();
    }

    public onDestroy() {
        this.removeListener();
    }

    private onScreenSwitch(): void {
        let sprite = this.node.getComponent(Sprite)
        if (sprite) {
            if (Global.gameScreenType == ScreenType.Landscape) {
                if (this.horSpr) sprite.spriteFrame = this.horSpr
            } else {
                if (this.verSpr) sprite.spriteFrame = this.verSpr
            }
        }
    }

    private updateNodePos(node: Node, updateParent: Node) {

    }

    private addListener(): void {
        Eventer.getInstance().on(GameEventType.ScreenSwitch, this.onScreenSwitch, this);
    }

    private removeListener(): void {
        Eventer.getInstance().offName(GameEventType.ScreenSwitch, this);
    }
}

