import { _decorator, Component, Label, UITransform, Node } from 'cc';
import { betListBoard } from './betListBoard';
import { RollBottom } from '../RollBottom';
import { RollCommonModel } from '../../RollCommonModel';
import GamesData from '../../../../gamesCommon/script/GamesData';
const { ccclass, property } = _decorator;
/**常态  选中状态*/
export enum BetBtnState {
    Nor,
    Check,
}
@ccclass('betListBtn')
export class betListBtn extends Component {
    /**常态  选中状态*/
    private _state = BetBtnState.Nor
    /**bet的位置 0:上  1:中  2:下*/
    private _isTop: boolean = false;
    private _isMid: boolean = false;
    private _isBottom: boolean = false;
    private HeightGroup: number[][] = [[46, 42, 72], [70, 60, 70]]
    private screenType: number = 0; // 1:横屏 2:竖屏 
    /**下标和值*/
    private _index: number = -1;
    private _value: number = 0;

    public get index(): number {
        return this._index;
    }
    public set index(value: number) {
        this._index = value;
    }

    public get value(): number {
        return this._value;
    }
    public set value(value: number) {
        this._value = value;
        let line = RollCommonModel.getInstance().curBetLine + RollCommonModel.getInstance().doubleLine
        let bet = value * line * RollCommonModel.getInstance().betRate;
        let score = GamesData.formatScore(bet, false);
        this.betValue.string = score.toString();
    }

    public get state() {
        return this._state;
    }
    public set state(value) {
        this._state = value;
    }
    @property(Label)
    private betValue: Label = null
    @property(Node)
    private lineNode: Node = null
    /**
     * 初始化Item
     * @param index bet数组的下标
     * @param value bet 的值
     * @param site  bet的位置 0:上  1:中  2:下
     */
    public init(index: number, value: number, site: number, screenType) {
        this.screenType = screenType
        this.index = index;
        this.value = value;
        this.setSite(site)
        // 把节点启用
        this.node.active = true;
    }

    /**设置当前选中按钮*/
    public setCheckBtn(enable: boolean) {
        this.betValue.fontSize = enable ? 28 : 22
    }
    /**更新betList的值*/
    public updateBet(value: number) {
        this.value = value
    }

    /**设置节点的高度和线的位置*/
    private setSite(site: number) {
        let height = this.HeightGroup[this.screenType - 1][0];
        let lineSite = -this.HeightGroup[this.screenType - 1][0] / 2;
        switch (site) {
            case 0:
                this._isTop = true
                break
            case 1:
                this._isMid = true
                break
            case 2:
                this._isBottom = true
                break
        }
        height = this.HeightGroup[this.screenType - 1][site]
        lineSite = -height / 2
        if (this._isBottom) {
            this.betValue.node.setPosition(this.betValue.node.position.x, this.screenType == 1 ? 14 : 10)
            this.lineNode.active = false
        }

        this.setNodeHeight(height)
        this.lineNode.setPosition(this.lineNode.position.x, lineSite)
    }
    private setNodeHeight(height) {
        this.node.getComponent(UITransform).height = height;
    }

    start() {

    }

    update(deltaTime: number) {

    }
}


