import { Component, Label, _decorator, Node, Sprite, Layers, SpriteFrame, UITransform, RichText } from "cc";
import { ResManager } from "../../../../../scripts/framework/manager/ResManager";
import GamesData from "../../../../gamesCommon/script/GamesData";
import { RollBottomWinLineBaseComp } from "./RollBottomWinLineBaseComp";
import { RollBottomWinLineVo } from "../RollBottom";
import { Global } from "../../../../../scripts/main/Global";
import i18n from "../../../../../scripts/framework/language/i18n";
const { ccclass, property } = _decorator;

@ccclass('RollBottomWinLineComp1')
export class RollBottomWinLineComp1 extends RollBottomWinLineBaseComp {

    @property(Node)
    imgNode: Node;

    @property(RichText)
    lineTipLab: RichText;

    /** 中线数节点 */
    @property(RichText)
    lineLab: RichText;

    /** 赢分节点 */
    @property(RichText)
    paysLab: RichText;

    /** 图标列表 */
    private _iconsList: Node[] = [];

    protected start(): void {

    }

    protected onLoad(): void {

    }

    /**
     * 设置数据
     * @param data 
     */
    public setData(data: RollBottomWinLineVo) {
        let resList = data.resList;
        let lineId = data.lineId;
        let iconWin = data.iconWin;
        let rateNum = data.rateNum;

        this.hideIcon();

        for (let i = resList.length - 1; i >= 0; i--) {
            if (!this._iconsList[i]) {
                let icon = this.icon();
                this._iconsList[i] = icon;
            }
            this._iconsList[i].setSiblingIndex(0)
            let res = resList[i];
            if (res instanceof SpriteFrame) {
                //精灵帧
                this.setSpriteFrame(this._iconsList[i], res);
            } else {
                //资源路径
                ResManager.Instance().load(GamesData.gameId.toString(), res as string, SpriteFrame, () => { }, (evt: any) => {
                    let spriteFrame: SpriteFrame = evt.data;
                    this.setSpriteFrame(this._iconsList[i], spriteFrame);
                });
            }
        }

        let formula = '';
        if (rateNum > 1) {
            // iconWin *= rateNum;
            let totalWin = iconWin * rateNum;
            formula = `${Global.currencyName}${GamesData.formatMoney(iconWin)} x ${rateNum}  = ${Global.currencyName}${GamesData.formatMoney(totalWin)}`;
        } else
            formula = `${Global.currencyName}${GamesData.formatMoney(iconWin)}`


        this.lineTipLab.string = i18n.tr(3002013);
        this.lineLab.string = i18n.tr(3002010, lineId.toString());
        this.paysLab.string = i18n.tr(3002006, formula);
    }

    private hideIcon() {
        for (let key in this._iconsList) {
            this._iconsList[key].active = false;
        }
    }

    /**
     * icon node
     * @returns 
     */
    private icon(): Node {
        let node = new Node();
        node.addComponent(Sprite);
        node.layer = Layers.Enum.UI_2D;
        this.imgNode.addChild(node);
        node.setSiblingIndex(0);
        return node;
    }

    protected onDestroy(): void {
    }
}