    /** 
     * 检测是否有连点暂停
     * 连点CST_STOP_NUM次暂停后，弹窗提示是否开启快速旋转
     * 中断连点则重新计算次数
     */
    public checkCstStopState() {
        if (this.cstState)
            this._cstStopNum = 0;
        this.cstState = true;
    }

    /** '连续多局点击 stop 按钮'次数 */
    private _cstStopNum: number = 0;
    /** '连续多局点击 stop 按钮'次数 */
    public get cstStopNum(): number {
        return this._cstStopNum;
    }
    /** 增加'连续多局点击 stop 按钮'次数 */
    public addCstStopNum() {
        if (Global.quickSpin)
            return;
        if (this.cstState) {
            this._cstStopNum++;
        }
        this.cstState = false;
        if (this.cstStopNum >= RollConst.CST_STOP_NUM) {
            this._cstStopNum = 0;
            //弹窗时间间隔
            let now = Date.now();
            if (now - this._cstStopTime > RollConst.CST_INTERVAL_TIME) {
                this._cstStopTime = now;
                UIManager.getInstance().open(UIID_GAME.UIRollQuickSpin);
            }
        }
    }

