    /**
     * 获取滚轮tips字段
     * @param key tipsKey
     * @param params 需要替换的参数
     * @returns 
     */
    public getTipsStrByKey(key: string, params: any[] = null): string {
        if (!key) {
            Log.e("getTipsStrByKey 的 key 不能为空！！");
            return null
        }
        if (!this._tipsCfg) {
            Log.d("_tipsCfg 还没初始化！");
            return null
        }
        let mLanguage: string = GamesData.getGameLanguageStr();
        key = key + "_" + mLanguage;

        let text = this._tipsCfg[key];
        if (!text) {
            return null
        }
        text = GamesData.replaceString(text, params);
        return text;
    }

    /**
     * 当押注值不在虚宝卡列表时，强制显示押注值
     * 公共接口，我真的是没地方写了。。。
     */
    public setBetForXBK(curBet: number, labBet: RichText | Label) {
        let line = this.curBetLine;
        let bet = curBet * line * this.betRate;
        let score = GamesData.formatScore(bet, false);
        labBet.string = i18n.tr(3002010, `${Global.currencyName}${score}`);
    }
