import { _decorator, Component, Node, Sprite, SpriteFrame } from 'cc';
import { ResManager } from '../../../../scripts/framework/manager/ResManager';
import { UIButton } from '../../../../scripts/framework/ui/basic_ui/UIButton';
import { UIView } from '../../../../scripts/framework/ui/UIView';
import { Global } from '../../../../scripts/main/Global';
import GamesData from '../../../gamesCommon/script/GamesData';
const { ccclass, property } = _decorator;

@ccclass('HelpView2')
export class HelpView2 extends UIView {
    @property(Sprite)
    introduceSp: Sprite = null;
    @property(UIButton)
    btnClose: UIButton = null;

    init(...args): void {

        let mLanguage: string = GamesData.getGameLanguageStr();
        let path = `resources/atlas/help/help0_${mLanguage}/spriteFrame`;
        ResManager.Instance().load(GamesData.gameId + "", path, SpriteFrame, () => { }, (evt: any) => { this.introduceSp.spriteFrame = evt.data; });

        this.btnClose.touchEndedFun = this.onBack.bind(this);
    }

    private onBack(target: UIButton): void {
        this.close();
    }

    protected onDestroy(): void {
        this.introduceSp = null;
        if (this.btnClose) {
            this.btnClose.touchEndedFun = null;
        }
        this.btnClose = null;
    }
}

