import { EventAcceleration, Input, input, JsonAsset, } from "cc";
import { ResManager } from "../../../../scripts/framework/manager/ResManager";
import GamesData from "../../../gamesCommon/script/GamesData";
import { BUNDLE_NAME } from "../../../gamesCommon/script/UIGameDefined";
import { ExtendEvent } from "./ExtendEvent";

export class ShakeTool extends ExtendEvent {
    /**摇动事件 */
    public static OnShakeEvent = "OnShakeEvent";

    private static _instance: ShakeTool;
    public static get instance(): ShakeTool {
        if (!this._instance) {
            this._instance = new ShakeTool();
        }
        return this._instance;
    }

    private constructor() {
        super();
    };

    /**功能被暂停使用 */
    private _pauseTimes = 0;

    private _config: ShakeConfig;

    private _isOpenShake = false;

    private _lastShakeTime = 0;
    private _lastEventTime = 0;
    private _curShakeCount = 0;
    private _last_x = 0;
    private _last_y = 0;
    private _last_z = 0;

    public clean(): void {
        this._pauseTimes = 0;
        this._isOpenShake = false;
        this._lastShakeTime = 0;
        this._lastEventTime = 0;
        this._curShakeCount = 0;
        this._last_x = 0;
        this._last_y = 0;
        this._last_z = 0;

        if(this._config)
        {
            this._config.isDefaultOpen = false;
            this._config.shakeCount = 1;
            this._config.shakeRate = 50;
            this._config.shakeWait = 120;
            this._config.shakeRange = 5;
        }
    }

    public get isOpenShake() {
        return this._isOpenShake;
    }

    public set isOpenShake(open: boolean) {
        this._isOpenShake = open;
        // if (this._isOpenShake) {
        //     input.setAccelerometerEnabled(true);
        //     input.on(Input.EventType.DEVICEMOTION, this._onAccelerationChange, this);
        // }
        // else {
        //     input.setAccelerometerEnabled(false);
        //     input.off(Input.EventType.DEVICEMOTION, this._onAccelerationChange, this);
        // }
    }

    /**初始化 */
    public init() {
        this._config = new ShakeConfig();
        let path: string = GamesData.ZAXIANG_URL;
        ResManager.Instance().load(BUNDLE_NAME.gamesCommon, path, JsonAsset, () => { }, (evt: any) => { this._readConfig(evt.data.json) });
    }

    private _readConfig(jsonObj: any) {
        if (jsonObj.json["shake"]) {  //初始化 摇一摇配置
            let conf = jsonObj.json["shake"];
            if (conf["isDefaultOpen"] != undefined) {
                this._config.isDefaultOpen = conf["isDefaultOpen"];
            }

            if (conf["shakeCount"] != undefined) {
                this._config.shakeCount = conf["shakeCount"];
            }

            if (conf["shakeRange"] != undefined) {
                this._config.shakeRange = conf["shakeRange"];
            }

            if (conf["shakeRate"] != undefined) {
                this._config.shakeRate = conf["shakeRate"];
            }

            if (conf["shakeWait"] != undefined) {
                this._config.shakeWait = conf["shakeWait"];
            }
        }
        this.isOpenShake = this._config.isDefaultOpen;
    }

    /**暂停功能使用 */
    public pause() {
        this._pauseTimes += 1;
    }

    /**功能继续使用 */
    public resume() {
        this._pauseTimes -= 1;
        if (this._pauseTimes <= 0) {
            this._pauseTimes = 0;
        }
    }

    /**设备加速计变化监听 */
    private _onAccelerationChange(evt: EventAcceleration) {
        Log.d("shake input:", evt.acc);
        if (this._pauseTimes > 0) {
            return;
        }
        let time = evt.acc.timestamp;
        let x = evt.acc.x;
        let y = evt.acc.y;
        let z = evt.acc.z;
        if (time - this._lastEventTime < this._config.shakeWait) {
            return;
        }
        if (time - this._lastShakeTime < this._config.shakeRate) {
            return;
        }
        this._lastShakeTime = time;
        let range = this._config.shakeRange;
        let delta_x = Math.abs(x - this._last_x);
        let delta_y = Math.abs(y - this._last_y);
        let delta_z = Math.abs(z - this._last_z);
        if (delta_x > range || delta_y > range || delta_z > range) {
            this._last_x = x;
            this._last_y = y;
            this._last_z = z;
            this._curShakeCount++;
        }

        if (this._curShakeCount > this._config.shakeCount) {
            this.emit(ShakeTool.OnShakeEvent);
            this._curShakeCount = 0;
            this._lastEventTime = time;
        }
    }

}

export class ShakeConfig {
    /**默认是否开启 */
    public isDefaultOpen: boolean = false;
    /**摇动次数，检测到此次数有效摇动则分发事件，重置次数*/
    public shakeCount: number = 1;
    /**摇动检测间隔 ms */
    public shakeRate: number = 50;
    /**一次有效事件后，暂停此时长继续下一次检测 */
    public shakeWait: number = 120;
    /**摇摆幅度 xyz轴上加速度超过此值才检测 */
    public shakeRange: number = 5;
}