import { _decorator, Component, Label, Node, RichText, UITransform } from 'cc';
const { ccclass, property } = _decorator;

@ccclass('RollRichTextFuncComp')
export class RollRichTextFuncComp extends Component {

    /** 限制宽 */
    @property(Number)
    labMaxWidth: number = 0;

    /** 是否加粗 */
    @property(Boolean)
    bold: boolean = false;

    /** 是否描边 */
    @property(Boolean)
    outline: boolean = false;
    /** 描边颜色 */
    @property(String)
    outlineColor: string = 'FFFFFF';

    start() {
    }

    update(deltaTime: number) {
        if (this.labMaxWidth > 0)
            if (this.width > this.labMaxWidth) {
                let scale = this.labMaxWidth / this.width;
                this.node.setScale(scale, scale);
            }
    }

    /**
     * 设置txt
     * @param lab 
     * @param str 
     */
    setText(lab: RichText, str: string) {
        if (this.bold)
            str = `<b>${str}</b>`
        if (this.outline)
            str = `<outline color=#${this.outlineColor} width=2>${str}</outline>`
        lab.string = str;
    }

    get maxWidth(): number {
        return this.node.getComponent(RichText).maxWidth;
    }
    get width(): number {
        return this.node.getComponent(UITransform).width;
    }
}

