import { TweenEasing } from "cc";


export class RollConst {
    /** '连续局数点击 stop 按钮'弹窗提示次数 */
    static readonly CST_STOP_NUM: number = 5;
    /** '连续局数点击 stop 按钮'生效间隔时间 */
    static readonly CST_INTERVAL_TIME: number = 300000;
    /**飘字时间 */
    static readonly TWEEN_TIME: number = 0.5;
    /**飘字Tween类型 */
    static readonly TWEEN_EASING: TweenEasing = "circIn";
    /** 默认押注提示 */
    static readonly DEFAULT_PLAYER_BET_TIPS = [
        3002001,
        3002002,
        3002003
    ]

    /** 默认没中奖提示 */
    static readonly PLAYER_BET_NOT_WIN_TIPS = 3000004;

    /** 没有竖屏状态的游戏 */
    static readonly WITHOUT_PORTRAIT_STATUS = [
        3000187,
        3000188,
        3000189,
        3000191
    ]

    /**
     * 获取游戏是否有竖屏状态
     */
    static isHasPotrait(gameId: number): boolean {
        let idx = this.WITHOUT_PORTRAIT_STATUS.indexOf(gameId);
        if (idx >= 0)
            return false;
        return true;
    }
}


/** 滚轮按钮状态 */
