import { AssetManager, AudioClip, AudioSource, Component, Label, RichText, Vec3, _decorator, assetManager } from "cc";
import { BmpLableComp } from "../../../gamesCommon/script/common/BmpLableComp";
import GamesData from "../../../gamesCommon/script/GamesData";
import { RollRichTextFuncComp } from "./RollRichTextFuncComp";
import { ResManager } from "../../../../scripts/framework/manager/ResManager";
import { BUNDLE_NAME } from "../../../gamesCommon/script/UIGameDefined";
const { ccclass, property } = _decorator

@ccclass("RollValue")
// @requireComponent(Label)
export class RollValue extends Component {

    // @property({
    //     type: AudioClip,
    //     displayName: '滚动音效'
    // })
    // private rollAudioClip: AudioClip;

    private _label: Label | BmpLableComp | RichText;
    public get lable(): Label | BmpLableComp | RichText {
        if (!this._label) {
            this._label = this.node.getComponent(Label);
            if (!this._label) {
                this._label = this.node.getComponent(BmpLableComp);
            }
            if (!this._label) {
                this._label = this.node.getComponent(RichText);
            }
        }
        return this._label;
    }
    // protected set lable(val:)
    private _endValue = 0;  //最终值
    private _startValue = 0; //开始值
    private _tempValue = 0;  //中间值
    private _isRolling = false;  //是否在滚动
    private _curTime = 0;   //当前时间 ms
    private _duration = 1000;  //时长1000ms
    private _prefix = "";   //显示前缀
    private _rollValue = 0;
    private _callBack: Function;
    private _caller: any;

    private _isMoney = false;
    // private _forceWidth = 0;
    // private _primaryScale: Vec3;

    /** 当前值 */
    public get tempValue(): number {
        return this._tempValue;
    }

    // protected __preload(): void {
    // }

    public init(isMoney: boolean, forceWidth = 0, duration = 1000, prefix = "") {
        this._isMoney = isMoney;
        // this._forceWidth = forceWidth;
        this._duration = duration;
        this._prefix = prefix;

        this.lable.string = "";
        // this._primaryScale = this.node.getScale().clone();
    }

    protected update(deltaTime: number) {
        if (!this._isRolling) {
            return;
        }
        this._curTime += deltaTime * 1000;
        let rate = this._curTime / this._duration;
        if (rate >= 1) {
            this.setValue(this._endValue);  //停止滚动
            return;
        }
        this._tempValue = this._startValue + rate * (this._endValue - this._startValue);
        let txt = this._prefix + this._formatValue(this._tempValue);
        this.setText(txt);
    }

    /**获取滚动的分数 */
    public get rollvalue() {
        return this._rollValue;
    }

    /**
     * 设置数值，不滚动增加
     * @param value 数值
     */
    public setValue(value: number) {
        let isRoll = this._isRolling
        this._isRolling = false;
        this._endValue = value;
        let txt = this._prefix + this._formatValue(value);
        this.setText(txt);
        if (this._callBack && this._caller) {
            this._callBack.call(this._caller, isRoll);
        }
    }

    /**
     * 停止滚动并设置最终值
     */
    public stopRoll() {
        let value = this._endValue;
        this.setValue(value);
    }

    /**
     * 数值滚动增加
     * @param add 增加值
     * @param isRoll 是否滚动，默认是，否则直接增加
     * @param duration 时间长度 ms
     */
    public addValue(add: number, isRoll = true, duration?: number) {
        let total = this._endValue + add;
        if (isRoll) {
            this._curTime = 0;
            if (duration != undefined) {
                this._duration = duration;
            }
            if (this._isRolling) {
                this._startValue = this._tempValue;
            }
            else {
                this._startValue = this._endValue;
            }
            this._endValue = total;
            this._isRolling = true;
        }
        else {
            this.setValue(total);
        }
    }

    /**
     * 数值滚动增加到
     * @param value 增加到值
     * @param isRoll 是否滚动，默认是，否则直接增加
     * @param duration 时间长度 ms
     */
    public addValueTo(value: number, isRoll = true, duration?: number) {
        let add = value - this._endValue;
        if (add <= 0)
            return;
        this.addValue(add, isRoll, duration);
    }

    /**
     * 设置label显示
     * @param txt 显示字符串
     */
    public setText(txt: string) {
        let richFunc = this.lable.getComponent(RollRichTextFuncComp);
        if (richFunc) {
            richFunc.setText(this.lable as RichText, txt);
        } else {
            this.lable.string = txt;
        }
    }

    private _formatValue(value: number) {
        this._rollValue = value;
        if (this._isMoney) {
            let money = GamesData.formatMoney(value);
            return money;
        }
        else {
            return GamesData.formatScore(value);
        }
    }

    public setCallback(cb: Function, _caller: any) {
        this._callBack = cb
        this._caller = _caller
    }

    public getEndValue() {
        return this._endValue
    }

    public setPrefix(str: string) {
        this._prefix = str
    }

    public get isRolling() {
        return this._isRolling;
    }

    //同步另一个RollValue的状态
    public updateFromOther(other: RollValue) {
        // this.stopRoll()
        // this.setValue(rollvalue._tempValue)
        // if (rollvalue.isRolling) {
        //   this.addValueTo(rollvalue.getEndValue())
        // } else {
        //   this.setValue(rollvalue.getEndValue())
        // }
        if (!other.isRolling) {
            this.setValue(other._endValue);
        } else {
            this._isRolling = true;
            this._startValue = other._startValue;
            this._endValue = other._endValue;
            this._curTime = other._curTime;
            this._duration = other._duration;
            let txt = this._prefix + this._formatValue(other._tempValue);
            this.setText(txt);
        }
    }

}