import { instantiate, Label, Layout } from 'cc';
import { _decorator, Component, Node } from 'cc';
import { betListBtn } from './betListBtn';
const { ccclass, property } = _decorator;

@ccclass('betListBoard')
export class betListBoard extends Component {
    @property(Node)
    public boardBG: Node = null
    // /**是否初始化过*/
    // private isInit: boolean = false
    public checkItem: betListBtn = null

    public initBetLIst(betList: number[], screenType): betListBtn[] {
        if (betList && betList.length > 0) {
            let betBtn = []
            // this.isInit = true
            let lenght = betList.length
            this.removeItem()
            for (let index = 0; index < lenght; index++) {
                let betvalue = betList[index]
                let site = 1
                if (index == 0) site = 2
                if (index == lenght - 1) site = 0
                let item = this.getItem()
                let btnCtr: betListBtn = item.getComponent(betListBtn)
                if (!btnCtr) btnCtr = item.addComponent(betListBtn)
                btnCtr.init(index, betvalue, site, screenType)
                this.node.addChild(item)
                betBtn.push(btnCtr)
            }
            this.node.active = false
            return betBtn
        }

    }
    private removeItem() {
        for (let i = 0; i < this.node.children.length; i++) {
            if (i != 0) {
                if (this.node.children[i])
                    this.node.children[i].removeFromParent()
                if (this.node.children[i])
                    this.node.children[i].destroy()
            }

        }
    }
    private getItem() {
        let btn_white = this.node.getChildByName("btn_white")
        let item = instantiate(btn_white)
        return item
    }

    start() {

    }

    update(deltaTime: number) {

    }
}


