import { _decorator, Node, sp, Animation, NodeEventType, AudioClip, AudioSource, math } from 'cc';
import { Resource } from '../../../../scripts/framework/hall/Resource';
import AudioManager from '../../../../scripts/framework/manager/AudioManager';
import { ResManager } from '../../../../scripts/framework/manager/ResManager';
import { ScreenType, UIView } from '../../../../scripts/framework/ui/UIView';
import { Global } from '../../../../scripts/main/Global';
import GameResPath from '../../../gamesCommon/script/constDatas/GameResPath';
import GamesData from '../../../gamesCommon/script/GamesData';
import { BUNDLE_NAME } from '../../../gamesCommon/script/UIGameDefined';
import { BigWinType, BigWinViewData } from '../RollCommonModel';
import { RollValue } from './RollValue';
const { ccclass, property } = _decorator;

@ccclass('BigWinView')
export class BigWinView extends UIView {

    @property(Node)
    private touchNode: Node;
    @property(Node)
    private eff: Node;
    @property(RollValue)
    private lab_bigWin: RollValue;
    @property(RollValue)
    private lab_jackPot: RollValue;
    @property(sp.Skeleton)
    private ske_major: sp.Skeleton;
    @property(sp.Skeleton)
    private ske_bigwin: sp.Skeleton;

    private _curSke: sp.Skeleton;
    private _curLab: RollValue;

    private _rolling = true;

    private _data: BigWinViewData;
    private _audioSource: AudioSource = null!;

    // update(deltaTime: number) {
    // }

    init(...args): void {
        this._data = args[0];
    }

    start() {
        this.changeScreen();
        this.lab_bigWin.init(false, 594);
        this.lab_jackPot.init(false, 594);
        this._showSkeleton();
        this.eff.getComponent(Animation).play("eff-in");

        this.touchNode.on(NodeEventType.TOUCH_END, this.onTouch, this);

        if (Global.backgroundMusic) {
            GamesData.stopBgMusic();

            this._audioSource = this.node.getComponent(AudioSource)!;
            if (!this._audioSource) {
                this._audioSource = this.node.addComponent(AudioSource)!;
                this._audioSource.playOnAwake = false;
                this._audioSource.loop = false;
            }
            this.playWinBg();
        }

        let autoCloseTime: number = Math.ceil(this._data.delay / 1000) + 3;

        this.scheduleOnce(() => {
            this._rolling = false;
            if (this._data.autoHide) {
                this._hide();
            }
        }, autoCloseTime);
    }

    // public onDestroy() {
    // }

    private playWinBg(): void {
        ResManager.Instance().load(
            BUNDLE_NAME.rollCommon,
            GameResPath.getRollCommonSound("bigwin"),
            AudioClip,
            () => { },
            (resCache: Resource.CacheData) => {
                // this._audioSource.stop();
                let clip: any = resCache.data;
                this._audioSource.clip = clip;
                this._audioSource.play();
            }
        );
    }

    private _showSkeleton() {
        this.ske_bigwin.node.active = false;
        this.ske_major.node.active = false;

        let typeName: string = this._data.type;
        if (typeName == "platform") {
            typeName = BigWinType.JACKPOT;
        }

        let skin: string = typeName;
        switch (typeName) {
            case BigWinType.BIG_WIN://"big-win":
            case BigWinType.MEGA_WIN://"mega-win":
            case BigWinType.SUPER_WIN://"super-win":
            case BigWinType.EPIC_WIN://"super-win":
            case BigWinType.ULTRA_BIG_WIN://"ultra-big-win":
            case BigWinType.ULTRA_MEGA_WIN://"ultra-mega-win":
                this._curSke = this.ske_bigwin;
                this._curLab = this.lab_bigWin;
                break;
            case BigWinType.JACKPOT://"jackpot":
            case BigWinType.MAJOR://"major":
            case BigWinType.MINOR://"minor":
            case BigWinType.RANDOM://"random":
                this._curSke = this.ske_major;
                this._curLab = this.lab_jackPot;
                break;
        }

        this._curLab.addValueTo(this._data.value, true, this._data.delay);
        this._rolling = true;

        this._curSke.node.active = true;
        this._curSke.setSkin(skin);
        this._curSke.setAnimation(0, "1-in", false);
        this._curSke.setCompleteListener((track) => {
            this._aniLoop();
        });
    }

    /**
     * 播放循环动画
     */
    private _aniLoop() {
        this._curSke.setCompleteListener(null);
        this.eff.getComponent(Animation).play("eff-loop");
        this._curSke.clearTrack(0);
        this._curSke.setAnimation(0, "2-loop", true);
    }

    private onTouch(evt) {
        if (this._rolling) {
            this._curLab.stopRoll();
            this._rolling = false;
        }
        else {
            this._hide();
            if (Global.backgroundMusic) {
                GamesData.playMusic();
            }
        }
    }

    private _hide() {
        this.touchNode.off(NodeEventType.TOUCH_END, this.onTouch, this); //防止隐藏过程中再次点击
        if (this._audioSource) {
            this._audioSource.stop();
            this._audioSource.destroy();
            this._audioSource = null;
        }

        this.eff.getComponent(Animation).play("eff-out");
        this._curSke.clearTrack(0);
        this._curSke.setAnimation(0, "3-out", false);
        this._curSke.setCompleteListener(() => {
            this.close();
            if (this._data.call && this._data.thisObj) {
                this._data.call.call(this._data.thisObj);
            }
        });
    }

    // 横竖屏切换显示
    private readonly _L_SCALE: math.Vec3 = new math.Vec3(1, 1, 1);
    private readonly _P_SCALE: math.Vec3 = new math.Vec3(0.56, 0.56, 0.56);
    private changeScreen(): void {
        let contentNode: Node = this.node.getChildByName("content").getChildByName("bigwin");
        if (Global.gameScreenType == ScreenType.Portrait) {
            contentNode.angle = 90;
            contentNode.setScale(this._P_SCALE);
        }
        else {
            contentNode.angle = 0;
            contentNode.setScale(this._L_SCALE);
        }
    }

}

