import { Node, UIOpacity } from "cc";
import { GameUtils } from "../../../../scripts/common/utils/GameUtil";
import { Eventer } from "../../../../scripts/framework/Eventer";
import i18n from "../../../../scripts/framework/language/i18n";
import { GameCommonModel } from "../../../gamesCommon/script/GameCommonModel";
import { GameEventType } from "../../../gamesCommon/script/GameEventType";
import { BigWinAudioName, BigWinShow, BigWinType, MaxRollWin, RollCommonModel } from "../RollCommonModel";
import { RollConst } from "../RollConst";

export class RollComUtils {

    
    /**
     * 根据倍率获取大奖类型
     * @param win 赢分
     * @param bet 总押注
     * @returns 大奖类型
     */
    static getBigWinTypeEmo(win?: number, bet?: number): BigWinType {
        let rates = win / bet;
        let type = null
        if(rates >= 3 && rates < 5){
            type = BigWinType.SHOW_COIN_WIN
        }
        else if(rates >= 5 && rates < 14){
            type = BigWinType.BIG_WIN //【Big Win】
        }
        else if(rates >= 14 && rates < 30){
            type = BigWinType.SUPER_WIN // 【Super Win】
        }
        else if(rates >= 30 && rates < 50){
            type = BigWinType.EPIC_WIN // 【Epic win】
        }
        else if(rates >= 50 && rates < 100){
            type = BigWinType.MEGA_WIN // 【Mega win】 
        }
        else if(rates >= 100){
            type = BigWinType.ULTRA_BIG_WIN // 【Ultimate win】
        }
        
        return type;
    }

    /**
     * 根据倍率获取大奖类型
     * @param win 赢分
     * @param bet 总押注
     * @returns 大奖类型
     */
    static getBigWinType(win: number, bet: number): BigWinType {
        let rate = win / bet;
        if (rate >= 1000) {
            return BigWinType.ULTRA_MEGA_WIN;
        }
        else if (rate >= 500) {
            return BigWinType.ULTRA_BIG_WIN;
        }
        else if (rate >= 100) {
            return BigWinType.MEGA_WIN;
        }
        else if (rate >= 50) {
            return BigWinType.SUPER_WIN;
        }
        else if (rate >= 20) {
            return BigWinType.BIG_WIN
        }
        return null;
    }

    /**
     * 根据大奖类型获取大奖音效名
     * @param type 
     * @param start 
     * @returns 
     */
    static getBigWinAudioName(type: BigWinType, start: boolean = true): string {
        switch (type) {
            case BigWinType.BIG_WIN:
                return start ? BigWinAudioName.BIG_WIN_START : BigWinAudioName.BIG_WIN;
            case BigWinType.MEGA_WIN:
                return start ? BigWinAudioName.MEGA_WIN_START : BigWinAudioName.MEGA_WIN;
            case BigWinType.SUPER_WIN:
                return start ? BigWinAudioName.SUPER_WIN_START : BigWinAudioName.SUPER_WIN;
                
            case BigWinType.EPIC_WIN:
                return start ? BigWinAudioName.EPIC_WIN_START : BigWinAudioName.EPIC_WIN;
            case BigWinType.ULTRA_BIG_WIN:
                return start ? BigWinAudioName.ULTRA_BIG_WIN_START : BigWinAudioName.ULTRA_BIG_WIN;
            case BigWinType.ULTRA_MEGA_WIN:
                return start ? BigWinAudioName.ULTRA_MEGA_WIN_START : BigWinAudioName.ULTRA_MEGA_WIN;
        }
        return '';
    }

    /**
     * 根据倍率获取大奖类型
     * @param win 赢分
     * @param bet 总押注
     * @returns 大奖类型
     */
    static getBigWinShow(win: number, bet: number): BigWinShow[] {
        let rate = win / bet;
        let result: BigWinShow[] = []
        if (rate >= 20) {
            let show = new BigWinShow()
            show.rate = rate >= 50 ? 50 : rate
            show.winType = BigWinType.BIG_WIN
            show.speed = 10
            show.loopTime = 5
            show.lastRate = 0
            result.push(show)
        }
        if (rate >= 50) {
            let show = new BigWinShow()
            show.rate = rate >= 100 ? 100 : rate
            show.winType = BigWinType.SUPER_WIN
            show.speed = 10
            show.loopTime = 5
            show.lastRate = 50
            result.push(show)
        }
        if (rate >= 100) {
            let show = new BigWinShow()
            show.rate = rate >= 500 ? 500 : rate
            show.winType = BigWinType.MEGA_WIN
            show.speed = 80
            show.loopTime = 5
            show.lastRate = 100
            result.push(show)
        }
        if (rate >= 500) {
            let show = new BigWinShow()
            show.rate = rate >= 1000 ? 1000 : rate
            show.winType = BigWinType.ULTRA_BIG_WIN
            show.speed = 100
            show.loopTime = 5
            show.lastRate = 500
            result.push(show)
        }
        if (rate >= 1000) {
            let show = new BigWinShow()
            show.rate = rate
            show.winType = BigWinType.ULTRA_MEGA_WIN
            show.speed = 200
            show.loopTime = 5
            show.lastRate = 1000
            result.push(show)
        }
        return result;
    }

    //大奖自动关闭时间
    static bigWinAutoCloseTime(): number {
        return 2
    }

    /**
     * @description: 是否达到最大赢取限制
     * @param {number} win
     * @return {*}
     */
    static checkMaxWinMoney(win: number): MaxRollWin {
        let slotCost = GameCommonModel.getInstance().slotCost;
        let maxLimit = GameCommonModel.getInstance().maxLimit
        let result: MaxRollWin = {
            isMax: false,
            maxWin: 0,
            win: win,
            showWin: win
        }
        if (!maxLimit || !slotCost) {
            return result
        }
        result.isMax = win >= slotCost * maxLimit
        result.maxWin = slotCost * maxLimit
        result.showWin = win >= slotCost * maxLimit ? slotCost * maxLimit : win
        return result
    }

    /** 随机默认提示 */
    static defaultBetTip(): string {
        let list = RollConst.DEFAULT_PLAYER_BET_TIPS;
        let id = GameUtils.randomInt(0, list.length);
        let str = i18n.tr(list[id]);
        return str;
    }

    /**
     * @description: 关闭功能列表，关闭自动模式选择界面，关闭快速旋转界面
     * @return {*}
     */
    static closeFuncUI() {
        //关闭功能列表
        Eventer.getInstance().emit(GameEventType.RollMenuViewClose);
        //自动模式选择界面
        Eventer.getInstance().emit(GameEventType.RollCloseAutoPlayMenu);
        //关闭快速旋转界面
        Eventer.getInstance().emit(GameEventType.RollQuickSpinClose);
    }

    /**
     * 
     * @param node 节点
     * @param flag 是否透明
     */
    static setBuyButtonOpacity(node: Node, flag: boolean) {
        let opacity = node.getComponent(UIOpacity);
        if (!opacity) {
            opacity = node.addComponent(UIOpacity);
        }

        if (!flag) {
            opacity.opacity = 255;
        } else {
            opacity.opacity = 255 * 0.7;
        }
    }

    /**
     * 音效音量
     * @param num 
     * @returns 
     */
    static getSoundVolume(num = 1) {
        return 1 / (0.6 + 0.4 * num)
    }
}

